/* SENDAS · Crónicas de Galilea — Vida en Galilea 1.3
   Motor narrativo sin desplazamiento de sprites, dependencias externas ni servicios de pago.
*/
(function(){
'use strict';
const KEY='sendas_cronicas_ilustrada_1';
const STORAGE_OK=(()=>{try{localStorage.setItem('__sendas_storage_probe','1');localStorage.removeItem('__sendas_storage_probe');return true;}catch(e){return false;}})();
const asset=name=>(window.__SENDAS_EMBEDDED__&&window.__SENDAS_EMBEDDED__[name])||('assets/'+name+'.webp');
const $=id=>document.getElementById(id);
const esc=str=>String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const saveData=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){}};
const readData=()=>{try{let obj=JSON.parse(localStorage.getItem(KEY)||'null');if(obj&&obj.version===1&&SCENES[obj.scene])return obj;}catch(e){} return null;};
function initialState(){return {version:1,scene:'home',inv:{agua:1,pan:1},flags:{},choices:{},visited:['home'],logs:['Amanece cerca de Cafarnaúm. Natán recuerda las palabras del Maestro.'],time:1,fontScale:1,completed:false};}
let renderSeq=0;
let state=initialState(),currentModal='',fishFrame=0,fishPos=0,knotStep=0,scriptStep=0,toastTimer=0;
const SCENES={
 home:{title:'Antes del amanecer',place:'Casa de Natán',art:'home',over:'UN NUEVO DÍA',body:()=> 'La luz del amanecer alcanza el patio de piedra. Antes de salir vuelves a recordar la nota que guardaste entre tus pertenencias.\n\nHace meses escuchaste al Maestro hablar del Reino de Dios. Hoy el pueblo te necesita; todavía no sabes cuánto cambiará este día.',acts:()=>[
  a('Examinar los utensilios del patio','field:home','◌'),a('Leer la nota que llevas en la bolsa','introLetter','✧'), a('Examinar tu cuaderno','journal','▤'),a('Salir hacia la aldea','go:village','↗')],spots:()=>[sp(75,63,'Patio','field:home'),sp(32,39,'Salir','go:village')]},
 village:{title:'Las voces del pueblo',place:'Aldea junto al lago',art:'village',over:'CAFARNAÚM · MAÑANA',body:()=> 'El pueblo despierta. Los pescadores revisan las redes, una familia prepara pan y las conversaciones se mezclan con el sonido del lago.\n\nJesús ha pasado por esta región. Sus palabras siguen circulando entre los vecinos, incluso entre quienes nunca lo han visto.',acts:()=>[
  a('Observar las casas y sus patios','field:village','◌'),a('Visitar a Irit, la curandera','go:irit','✦'),a('Caminar hacia el muelle','go:dock','≈'),a('Explorar el mercado','go:market','◇'),a('Buscar a Siméon','go:simeon','▤'),a('Subir a la colina','go:hill','⌃')],spots:()=>[sp(28,56,'Irit','go:irit'),sp(72,62,'Muelle','go:dock'),sp(48,35,'Mercado','go:market')]},
 market:{title:'Lo que cuesta una cuerda',place:'Mercado de la aldea',art:'market',over:'OFICIOS Y CAMINOS',body:()=> state.flags.cordBought?'Los comerciantes te reconocen. La cuerda que compraste todavía conserva olor a cáñamo.':'Bajo los toldos de tela se venden higos, sal, aceite y pequeñas herramientas. Un artesano muestra cuerdas de fibra vegetal; una mujer cuenta las últimas monedas de su bolsa.',acts:()=>[
 a('Examinar tejidos y recipientes','field:market','◌'),a('Hablar con Mara','talkMara','◎'),a('Comprar cuerda para una red','buyCord','◇'),a('Regresar a la plaza','go:village','←')],spots:()=>[sp(54,50,'Mara','talkMara'),sp(73,56,'Cuerda','buyCord')]},
 irit:{title:'El jardín de Irit',place:'Patio de la curandera',art:'irit',over:'UN FAVOR SENCILLO',body:()=> state.flags.iritDone?'Irit ha terminado de preparar el remedio. La casa vuelve a oler a hierbas frescas y agua templada.':'Irit ha atendido a medio pueblo desde antes del amanecer. Frente a su puerta se acumulan cestas vacías. Su sobrina está enferma y necesita descanso, agua y cuidado.',acts:()=>[
 a('Conversar con Irit','talkIrit','◎'),a('Ir al campo a buscar plantas','go:herbs','✦'),a('Volver a la plaza','go:village','←')],spots:()=>[sp(53,48,'Irit','talkIrit'),sp(27,65,'Campo','go:herbs')]},
 dock:{title:'Las redes de Jonás',place:'Muelle de los pescadores',art:'dock',over:'EL LAGO Y SUS OFICIOS',body:()=>state.flags.netDone?'La red ha quedado reparada. Jonás revisa los últimos nudos antes de volver a preparar la barca; el trabajo puede continuar.':'El olor de la madera mojada llena el embarcadero. Jonás sostiene una red rasgada. El viento hace chocar dos embarcaciones mientras su hijo recoge los plomos que se han soltado.',acts:()=>[
 a('Observar las barcas del lago','field:dock','◌'),a('Hablar con Jonás','talkJonas','◎'),a('Inspeccionar la red','inspectNet','⌁'),a('Ir a la orilla a pescar','go:shore','≈'),a('Volver a la plaza','go:village','←')],spots:()=>[sp(37,52,'Jonás','talkJonas'),sp(80,69,'Red','inspectNet'),sp(24,53,'Orilla','go:shore')]},
 shore:{title:'El agua parece tranquila',place:'Orilla del mar de Galilea',art:'shore',over:'NATURALEZA · PESCA',body:()=> 'Las ondas avanzan sobre las piedras claras. Algunos peces rompen la superficie antes de volver a la sombra.\n\nPara pescar no hace falta luchar: necesitas observar, esperar y tirar de la cuerda en el momento justo.',acts:()=>[
 a('Intentar pescar','fish','≈'),a('Observar las aguas','lookLake','◌'),a('Regresar al muelle','go:dock','←')],spots:()=>[sp(59,60,'Pescar','fish'),sp(21,65,'Muelle','go:dock')]},
 herbs:{title:'Lo pequeño también importa',place:'Campo de hierbas',art:'herbs',over:'NATURALEZA · RECOLECCIÓN',body:()=> 'Flores, hojas y semillas crecen entre las piedras. Irit te describió qué aspecto tienen las plantas que necesita.\n\nElegir con cuidado es más importante que recoger mucho.',acts:()=>[
 a('Identificar y recoger plantas','herbPuzzle','✦'),a('Observar el paisaje','lookHerbs','◌'),a('Volver con Irit','go:irit','←')],spots:()=>[sp(43,54,'Plantas','herbPuzzle'),sp(78,58,'Irit','go:irit')]},
 olive:{title:'Rastros entre los olivos',place:'Sendero de los olivos',art:'olive',over:'NATURALEZA · RASTREO',body:()=>state.flags.trackSolved?'Sabes qué animal pasó por aquí. Una senda estrecha conduce hacia unas rocas; más allá se oye la voz de alguien que pide ayuda.':'Hay huellas en el polvo. Una cabra se aleja por los bancales y, bajo un arbusto, un animal pequeño mueve las orejas. Puedes estudiar las señales antes de seguir.',acts:()=>[
 a('Observar los olivos y los molinos','field:olive','◌'),a('Examinar las huellas','track','⌖'),a('Seguir el sendero del norte','go:injured','↗'),a('Regresar a la aldea','go:village','←')],spots:()=>[sp(57,68,'Huellas','track'),sp(77,40,'Camino','go:injured')]},
 injured:{title:'El viajero de la senda',place:'Camino de la garganta',art:'injured',over:'UNA DECISIÓN QUE QUEDA',body:()=>state.flags.woundedChoice?'El hombre descansa junto al camino. Lo que has decidido no desaparecerá cuando vuelvas al pueblo.':'A la sombra de una roca encuentras a un hombre exhausto. Tiene una herida en el brazo y su cántaro está vacío. Dice que venía de Jerusalén.\n\nTus provisiones son limitadas. La aldea queda a cierta distancia.',acts:()=>[
 a('Acercarte y decidir cómo ayudar','wounded','✧'),a('Regresar a los olivos','go:olive','←')],spots:()=>[sp(43,56,'Viajero','wounded'),sp(77,40,'Regresar','go:olive')]},
 simeon:{title:'Las páginas de Siméon',place:'Casa del escriba',art:'simeon',over:'INVESTIGACIÓN · MANUSCRITOS',body:()=>state.flags.simeonPuzzle?'Has reunido los fragmentos de una nota sobre un manantial antiguo. Siméon prefiere no preguntarte qué harás con el descubrimiento.':'Siméon conoció al maestro de Natán. Su casa está llena de registros y tablillas. Un viejo cofre guarda una nota cifrada que nadie ha logrado ordenar.',acts:()=>[
 a('Hablar con Siméon','talkSimeon','◎'),a('Examinar el manuscrito','scriptPuzzle','▤'),a('Volver a la aldea','go:village','←')],spots:()=>[sp(52,43,'Siméon','talkSimeon'),sp(22,60,'Manuscrito','scriptPuzzle')]},
 spring:{title:'El agua escondida',place:'Manantial antiguo',art:'spring',over:'UN SECRETO ENTRE PIEDRAS',body:()=>state.flags.springSolved?'Detrás de las piedras hallaste un mensaje de tu maestro. No revela su paradero, pero explica por qué intentaba proteger a una familia.':'El manantial está casi seco. Un canal tallado en roca termina bajo un arco antiguo. Una inscripción fragmentada conserva referencias a un olivo, al agua y a una piedra.',acts:()=>[
 a('Investigar los canales y las señales','springPuzzle','⌖'),a('Explorar las ruinas próximas','go:ruins','▤'),a('Regresar a la aldea','go:village','←')],spots:()=>[sp(53,55,'Canales','springPuzzle'),sp(81,49,'Ruinas','go:ruins')]},
 ruins:{title:'Piedras que conservan memoria',place:'Ruinas del camino',art:'ruins',over:'DESCUBRIMIENTO OPCIONAL',body:()=>state.flags.ruinsSeen?'Anotaste el fragmento de pavimento y la cerámica. La época y el uso de estas ruinas imaginarias siguen siendo inciertos.':'Entre muros derrumbados se ven restos de cerámica, piedras gastadas y un fragmento de pavimento decorado. No sabes quién vivió aquí ni cuándo quedó abandonado. Hay una vasija que parece haber sido movida hace poco.',acts:()=>[
 a('Examinar los restos de cerámica','lookRuins','▤'),a('Volver al manantial','go:spring','←')],spots:()=>[sp(52,43,'Restos','lookRuins'),sp(22,76,'Atrás','go:spring')]},
 hill:{title:'Donde se reúne la multitud',place:'Colina sobre el lago',art:'hill',over:'LA PALABRA Y EL CAMINO',body:()=> 'Al atardecer encuentras una colina desde la que se ven los pequeños barcos. Familias, jornaleros, comerciantes y viajeros llegan por senderos distintos.\n\nUn rumor recorre la multitud: Jesús está enseñando cerca de allí.',acts:()=>[
 a('Acercarte para escuchar','go:jesus','↗'),a('Contemplar el lago','lookHill','◌'),a('Volver a la aldea','go:village','←')],spots:()=>[sp(57,48,'Multitud','go:jesus'),sp(16,65,'Lago','lookHill')]},
 jesus:{title:'Los que escuchan',place:'La enseñanza en la colina',art:'jesus',over:'MATEO 5,1–12 · PARÁFRASIS NARRATIVA',body:()=>state.completed?'El Maestro ya ha continuado su camino. La multitud se dispersa, pero algunas palabras permanecen. Natán vuelve a mirar el lago y se pregunta cómo vivirá lo que ha oído.':'Natán escucha a Jesús desde un lugar apartado de la multitud. Las bienaventuranzas hablan de los afligidos, de quienes trabajan por la paz y de la misericordia.\n\nLas palabras no parecen una respuesta sencilla. Le recuerdan la red de Jonás, el cansancio de Irit y al hombre encontrado en la senda.',acts:()=>[
 a('Reflexionar sobre lo escuchado','reflect','✧'),a('Regresar a explorar','go:village','←')],spots:()=>[sp(42,51,'Escuchar','reflect')]}
};
function a(label,id,icon){return {label,id,icon};} function sp(x,y,label,id){return{x,y,label,id};}
const ITEMS={agua:['Agua en un cántaro','Provisión para el camino.','jar'],pan:['Pan de cebada','Alimento sencillo para un viajero.','bread'],moneda:['Moneda','Pequeña moneda de cobre.','chest'],cuerda:['Cuerda de cáñamo','Fibra resistente para reparar redes.','net'],plantas:['Plantas recolectadas','Hojas y flores recogidas para Irit.','herb'],pez:['Pescado fresco','Alimento obtenido en la orilla.','fish'],red:['Red reparada','El trabajo de Jonás está terminado.','net'],nota:['Fragmento de manuscrito','Una pista del viejo maestro de Natán.','scroll'],mensaje:['Mensaje del manantial','Un testimonio oculto entre piedras.','scroll'],carne:['Alimento de caza','Un pequeño animal cazado en los olivos.','hare']};
function has(k,n=1){return (state.inv[k]||0)>=n;}
function gain(k,n=1){state.inv[k]=(state.inv[k]||0)+n;saveData();}
function spend(k,n=1){if(!has(k,n))return false;state.inv[k]-=n;if(state.inv[k]<=0)delete state.inv[k];saveData();return true;}
function flag(k){return !!state.flags[k];}
function setFlag(k){state.flags[k]=true;saveData();}
function remember(text){if(state.logs.indexOf(text)<0)state.logs.push(text);saveData();}
function progress(){return ['netDone','iritDone','springSolved'].filter(k=>flag(k)).length;}
function toast(msg){let el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2450);}
function closeModal(){cancelAnimationFrame(fishFrame);fishFrame=0;$('modal-root').hidden=true;$('modal-content').innerHTML='';currentModal='';}
function openModal(title,content,over='UN ENCUENTRO'){cancelAnimationFrame(fishFrame);fishFrame=0;$('modal-root').hidden=false;$('modal-title').textContent=title;$('modal-overline').textContent=over;$('modal-content').innerHTML=content;currentModal=title;setTimeout(()=>{let b=$('modal-content').querySelector('button');if(b)b.focus();},0);}
function btn(label,id,style=''){return `<button class="modal-choice ${style}" data-run="${esc(id)}">${esc(label)}<span>›</span></button>`;}
function dialog(name,portrait,desc,text,choices){let content=`<div class="dialog-head"><img class="portrait" src="${asset('portrait_'+portrait)}" alt="Retrato de ${esc(name)}"><div><div class="dialog-person">${esc(name)}</div><div class="dialog-desc">${esc(desc)}</div></div></div><div class="inline-separator"></div><p class="lead">${text}</p><div class="modal-actions">${choices.map(c=>btn(c[0],c[1])).join('')}</div>`;openModal('Una conversación',content,'HABLA CON '+name.toUpperCase());}
function simple(title,paragraph,choices=[['Continuar','modalClose']],over='DESCUBRIMIENTO'){openModal(title,`<p class="lead">${paragraph}</p><div class="modal-actions">${choices.map(c=>btn(c[0],c[1])).join('')}</div>`,over);}
function canGo(id){if(id==='hill'&&progress()<3){let missing=[];if(!flag('netDone'))missing.push('ayudar a Jonás con la red');if(!flag('iritDone'))missing.push('entregar las plantas a Irit');if(!flag('springSolved'))missing.push('seguir la pista del manantial');simple('Todavía queda camino','Antes de subir, Natán siente que aún tiene asuntos pendientes: '+esc(missing.join('; '))+'.');return false;}
 if(id==='jesus'&&!flag('hillVisited')){simple('Un sendero por descubrir','Primero debes llegar hasta la colina.');return false;}
 if(id==='spring'&&!flag('simeonPuzzle')){simple('No sabes dónde buscar','El manantial aparece en los recuerdos de Natán, pero necesitas una pista más concreta. Visita a Siméon.');return false;}
 if(id==='injured'&&!flag('trackSolved')){simple('Un rastro incierto','Necesitas observar las huellas antes de internarte en la garganta.');return false;}
 if(id==='ruins'&&!flag('springSolved')){simple('Una entrada escondida','Primero debes descubrir qué hay detrás de los canales del manantial.');return false;}
 return true;}
function go(id){if(!SCENES[id])return;if(!canGo(id))return;clearTimeout(toastTimer);$('toast').classList.remove('show');closeModal();state.scene=id;if(id==='hill')setFlag('hillVisited');if(state.visited.indexOf(id)<0)state.visited.push(id);state.time=Math.min(4,Math.floor(state.visited.length/5)+1);saveData();render(true);}
function render(animate){const scene=SCENES[state.scene];let art=$('scene-art');if(animate)art.classList.add('fading');const displayArt=(state.scene==='jesus'&&state.completed)?'epilogue':(state.scene==='village'&&progress()>=2)?'village_return':scene.art;const url=asset(displayArt),seq=++renderSeq;let im=new Image();im.onload=()=>{if(seq!==renderSeq)return;art.src=url;art.alt='Ilustración: '+scene.place;art.classList.remove('fading');requestAnimationFrame(positionHotspots);};im.onerror=()=>{if(seq!==renderSeq)return;art.src=url;art.classList.remove('fading');requestAnimationFrame(positionHotspots);};im.src=url;
 const afterTeaching=(state.scene==='jesus'&&state.completed);$('scene-badge').textContent=afterTeaching?'LA PALABRA PERMANECE':scene.over;$('scene-place').textContent=afterTeaching?'La noche junto al lago':scene.place;$('story-overline').textContent=afterTeaching?'CAPÍTULO I · NOCHE':'CAPÍTULO I · '+(state.time===1?'AMANECER':state.time===2?'MAÑANA':state.time===3?'TARDE':'ATARDECER');$('story-title').textContent=afterTeaching?'Lo que permanece':scene.title;$('story-body').textContent=scene.body();$('chapter-progress').textContent=progress()+' / 3';
 let actions=scene.acts();$('story-actions-count').textContent=actions.length+' ACCIONES';$('actions').innerHTML=actions.map(ac=>`<button class="action-btn" data-run="${esc(ac.id)}"><span class="action-icon">${esc(ac.icon)}</span><span class="action-copy">${esc(ac.label)}</span><span class="action-chevron">›</span></button>`).join('');
 $('hotspot-layer').innerHTML=scene.spots().map(h=>`<button class="hotspot" data-image-x="${h.x}" data-image-y="${h.y}" style="left:${h.x}%;top:${h.y}%" data-run="${esc(h.id)}" aria-label="${esc(h.label)}" title="${esc(h.label)}"><span class="hot-dot"></span><span class="hot-label">${esc(h.label)}</span></button>`).join('');
 $('scene-discovery').textContent=state.completed?'Capítulo completado · Sigue explorando.':STORAGE_OK?`${state.visited.length} lugares visitados · Guardado automático`:`${state.visited.length} lugares · Guardado limitado en este navegador`;
 $('story-panel').querySelector('.story-scroll').scrollTop=0;requestAnimationFrame(positionHotspots);document.documentElement.style.setProperty('--fontscale',String(state.fontScale||1));}
function showStart(){let save=readData();$('start-continue').hidden=!save;$('start-screen').hidden=false;}
function startNew(){state=initialState();gain('moneda',2);saveData();$('start-screen').hidden=true;render();simple('El principio del camino','Galilea, alrededor del siglo I. Natán es un joven seguidor de Jesús, aunque no forma parte de los Doce. Ayuda a los habitantes y descubre por qué desapareció su viejo maestro.\n\nToca una zona luminosa de la ilustración o elige una acción bajo la escena.',[['Comenzar','modalClose']],'PRÓLOGO');}
function startContinue(){let saved=readData();state=saved||initialState();$('start-screen').hidden=true;render();toast('Partida recuperada.');}

function castCards(){const cast=[['Nat&aacute;n','El viajero que decide seguir a Jes&uacute;s','natan'],['Irit','Curandera del pueblo','irit'],['Jon&aacute;s','Pescador del lago','jonas'],['Sim&eacute;on','Escriba y custodio de las pistas','simeon'],['Mara','Comerciante de la aldea','mara'],['Jes&uacute;s','El Maestro: representaci&oacute;n art&iacute;stica','jesus']];return `<div class="cast-section"><div class="section-overline">ROSTROS DEL CAMINO</div><div class="cast-gallery">${cast.map(c=>`<div class="cast-card"><img src="${asset('portrait_'+c[2])}" alt=""><strong>${c[0]}</strong><span>${c[1]}</span></div>`).join('')}</div><p class="cast-note">Im&aacute;genes imaginadas para la narraci&oacute;n: no son retratos hist&oacute;ricos.</p></div>`;}
function openJournal(){let logs=state.logs.map((l,i)=>`<div class="objective"><div class="objective-marker">${i+1}</div><div>${esc(l)}</div></div>`).join('');openModal('Diario de Natán',`<p class="lead">Cada experiencia deja una huella. No todas las respuestas aparecen el mismo día.</p><div class="chip-row"><span class="chip">${state.visited.length} lugares</span><span class="chip">${state.logs.length} recuerdos</span><span class="chip">${state.completed?'Capítulo terminado':'Camino abierto'}</span></div>${btn('Abrir cuaderno histórico','history')}${logs}${castCards()}<div class="reflection"><div class="quote-ref">REFERENCIAS DEL RELATO</div><p>Lucas 8,1–3: Jesús viaja por pueblos y aldeas con los Doce y otras personas que lo acompañan y apoyan. Natán es un personaje ficticio imaginado dentro de este contexto.</p><p>Mateo 5,1–12: las bienaventuranzas inspiran la reflexión final. Los diálogos ficticios no se presentan como citas bíblicas.</p></div>`,'EL DIARIO DEL VIAJERO');}
const FIELD_DETAILS={
 home:['Utensilios del patio','Observas recipientes, cestos y una piedra de molienda. La casa es ficticia, pero sus materiales recuerdan los hallazgos domésticos de Cafarnaúm.'],
 village:['Patios compartidos','Una misma vivienda podía abrirse a un patio de trabajo. Las calles y casas de esta aldea son recreaciones, no una planta arqueológica exacta.'],
 market:['Intercambio cotidiano','La cuerda, los tejidos y las vasijas no son mercancías de lujo: forman parte de un trabajo cotidiano. No conocemos el inventario preciso de este mercado ficticio.'],
 dock:['Construcción y pesca','La barca antigua hallada en Ginosar muestra que se empleaban embarcaciones de madera en el lago durante este periodo. Jonás y su red son ficción.'],
 olive:['Piedra de moler y olivos','Se han encontrado molinos de piedra y huellas de actividades con aceitunas en Cafarnaúm. Este sendero es imaginado.']
};
function showHistory(id){id=id&&window.SENDAS_HISTORY[id]?id:state.scene;const data=window.SENDAS_HISTORY||{};let h=data[id];if(!h){return simple('Cuaderno histórico','La ficha histórica de esta escena todavía no está disponible.');}const source=`<a class="history-source" href="${esc(h.url)}" target="_blank" rel="noopener noreferrer">Consultar fuente: ${esc(h.ref)} ↗</a>`;openModal('Galilea · '+esc(h.label),`<div class="history-status">${esc(h.level)}</div><p class="lead">${esc(h.fact)}</p><div class="reflection"><div class="quote-ref">MATERIALES Y TÉCNICAS</div><p>${esc(h.tech)}</p></div>${source}<div class="modal-actions">${btn('Volver al cuaderno','history')}${btn('Volver a la aventura','modalClose')}</div>`,'CONTEXTO HISTÓRICO');}
function openHistory(){let data=window.SENDAS_HISTORY||{};let seen=[...new Set(state.visited)].filter(id=>data[id]);let list=seen.map(id=>`<button class="history-entry" data-run="history:${esc(id)}"><span><strong>${esc(data[id].label)}</strong><small>${esc(data[id].level)}</small></span><span aria-hidden="true">›</span></button>`).join('');let fields=Object.keys(FIELD_DETAILS).filter(k=>flag('field_'+k)).length;openModal('Cuaderno histórico',`<p class="lead">Conoce la Galilea del siglo I sin confundir las evidencias con la ficción de Natán.</p><div class="chip-row"><span class="chip">${seen.length} lugares documentados</span><span class="chip">${fields} / 5 oficios observados</span></div><p class="muted">Las fichas separan lo excavado, lo reconstruido y lo inventado para esta aventura. No son certificaciones arqueológicas de las imágenes.</p>${list}<div class="modal-actions">${btn('Cerrar cuaderno','modalClose')}</div>`,'HISTORIA DEL MUNDO');}
function fieldObserve(id){const info=FIELD_DETAILS[id];if(!info)return;if(!flag('field_'+id)){setFlag('field_'+id);remember('Cuaderno de campo: '+info[0]+'.');}const discovered=Object.keys(FIELD_DETAILS).filter(k=>flag('field_'+k)).length;const extra=discovered===5?' Has observado los cinco aspectos de la vida cotidiana de esta región.':'';render();simple(info[0],esc(info[1])+extra,[['Leer la ficha histórica','history:'+id],['Seguir explorando','modalClose']],'CUADERNO DE CAMPO');}
function positionHotspots(){let layer=$('hotspot-layer'),im=$('scene-art'),box=$('scene-stage');if(!im.naturalWidth||!im.naturalHeight||!box.clientWidth||!box.clientHeight)return;let bw=box.clientWidth,bh=box.clientHeight,iw=im.naturalWidth,ih=im.naturalHeight,ratio=Math.max(bw/iw,bh/ih),renderWidth=iw*ratio,renderHeight=ih*ratio,ox=(bw-renderWidth)/2,oy=(bh-renderHeight)/2;layer.querySelectorAll('.hotspot').forEach(el=>{let px=Number(el.dataset.imageX)/100,py=Number(el.dataset.imageY)/100;let x=ox+px*renderWidth,y=oy+py*renderHeight;el.style.left=Math.max(69,Math.min(bw-69,x))+'px';el.style.top=Math.max(41,Math.min(bh-41,y))+'px';});}
function openInventory(){let keys=Object.keys(state.inv).filter(k=>state.inv[k]>0);let list=keys.length?keys.map(k=>{let it=ITEMS[k]||['Objeto','', 'chest'];return `<div class="item-row"><img class="item-art" src="${asset('item_'+it[2])}" alt=""><div><div class="item-label">${esc(it[0])}</div><div class="item-desc">${esc(it[1])}</div></div><div class="item-count">×${state.inv[k]}</div></div>`}).join(''):'<p>Tu bolsa está vacía.</p>';openModal('La bolsa de viaje',`<p class="muted">Los recursos no son una puntuación moral. Podrás utilizarlos en situaciones concretas.</p>${list}`,'INVENTARIO');}
function openObjectives(){let objs=[['Redes para Jonás','Consigue una cuerda y repara la red del pescador.',flag('netDone')],['El favor de Irit','Reúne dos plantas correctas y entrégaselas.',flag('iritDone')],['El rastro del maestro','Habla con Siméon y encuentra el mensaje del manantial.',flag('springSolved')],['La senda de los olivos','Observa las huellas y conoce a un viajero.',flag('trackSolved')],['Una decisión en el camino','Decide cómo responder al viajero herido.',flag('woundedChoice')],['La palabra de Jesús','Escucha las bienaventuranzas en la colina.',state.completed]];openModal('Tu camino',`<p class="muted">Las tres primeras tareas permiten avanzar en la historia. Las restantes enriquecen el desenlace.</p>${objs.map(o=>`<div class="objective ${o[2]?'done':''}"><div class="objective-marker">${o[2]?'✓':'·'}</div><div><strong>${esc(o[0])}</strong><small>${esc(o[1])}</small></div></div>`).join('')}`,'MISIONES Y DECISIONES');}
function openMap(){let names=['home','village','irit','market','dock','shore','herbs','olive','injured','simeon','spring','ruins','hill','jesus'];let places=names.map(k=>{let s=SCENES[k],lock=!state.visited.includes(k)||(k==='hill'&&progress()<3)||(k==='spring'&&!flag('simeonPuzzle'))||(k==='injured'&&!flag('trackSolved'))||(k==='ruins'&&!flag('springSolved'))||(k==='jesus'&&!flag('hillVisited'));return `<button class="${k===state.scene?'active':''} ${lock?'locked':''}" ${lock?'disabled':''} data-run="go:${k}">${esc(s.place)}<small>${lock?'Aún no descubierto':'Visitado'}</small></button>`}).join('');openModal('Las rutas de Galilea',`<img class="world-map" src="${asset('map')}" alt="Ilustración del paisaje y la costa de Galilea"><p class="muted">El mapa es una guía ilustrativa, no un sistema de movimiento. Elige un lugar: las rutas narrativas se abren con tus descubrimientos.</p><div class="places">${places}</div>`,'MAPA DEL VIAJERO');}
function help(){openModal('Cómo se juega',`<p>En esta aventura <strong>no tienes que conducir a Natán por un mapa</strong>. Cada lugar es una ilustración independiente. Toca los puntos luminosos o elige acciones y destinos bajo la imagen.</p><div class="note">Hablar → Investigar → Recoger → Usar → Decidir. Algunas actividades se pueden resolver de varias maneras; tus elecciones aparecen en el diario.</div><p>La historia se guarda automáticamente en este navegador. Las misiones principales están en «Camino». Los descubrimientos opcionales alteran el final.</p>${btn('Empezar a explorar','modalClose')}`,'AYUDA');}
function settings(){openModal('Opciones',`<div class="objective"><div><strong>Tamaño del texto</strong><small>Para leer con comodidad en móviles antiguos.</small></div></div><div class="modal-actions">${btn('Letra más grande','fontBigger')}${btn('Letra más pequeña','fontSmaller')}${btn('Exportar mi partida (JSON)','export')}${btn('Importar una partida (JSON)','import')}${btn('Volver a la portada','titleScreen')}${btn('Comenzar una partida nueva','resetConfirm')}</div><p class="qa-quiet">Juego sin conexión, sin cuentas, anuncios ni seguimiento. La partida se guarda cuando el navegador permite almacenamiento local. Algunos lectores de archivos Android bloquean esa función: usa GitHub Pages o exporta tu partida como JSON.</p>`,'CONFIGURACIÓN');}
function introLetter(){simple('Una carta doblada','«No siempre podemos seguir al Maestro por todos los caminos. Pero allí donde caminamos podemos decidir cómo tratar a los demás».\n\nEs una frase que Natán copió después de escuchar una enseñanza. No es una cita literal de los Evangelios.',[['Guardar la carta en el diario','keepLetter'],['Cerrar','modalClose']],'RECUERDO DE NATÁN');}
function talkJonas(){if(!flag('jonasTalk')){setFlag('jonasTalk');remember('Jonás necesita ayuda: su red se ha rasgado antes de la pesca.');}dialog('Jonás','jonas','Pescador de la aldea',flag('netDone')?'«Nunca olvidaré lo que hiciste, Natán. Cuando llegue la tarde compartiremos el pan».' : '«La red está hecha pedazos. Si encontramos un poco de cuerda fuerte podríamos remendarla. He oído que Mara tiene una en el mercado».' ,flag('netDone')?[['Preguntar por los seguidores del Maestro','jonasFaith'],['Despedirse','modalClose']]:[['Ofrecer ayuda con la red','inspectNet'],['Preguntar por Jesús','jonasFaith'],['Buscar cuerda en el mercado','go:market'],['Me iré por ahora','modalClose']]);}
function jonasFaith(){dialog('Jonás','jonas','Pescador de la aldea','«Conozco a algunos que dejaron sus redes para seguirlo. Yo no sé hacerlo. Pero sus palabras me hacen mirar a mis vecinos de otra manera».', [['Volver al muelle','modalClose']]);}
function inspectNet(){if(flag('netDone'))return simple('Una red firme','Las fibras ya están atadas. Jonás puede volver a trabajar.');if(!has('cuerda'))return simple('Faltan fibras','La red puede repararse, pero necesitas cuerda resistente. La encontrarás en el mercado.',[['Ir al mercado','go:market'],['Cerrar','modalClose']]);knotStep=0;repairPuzzle();}
function repairPuzzle(){const order=['Tensar','Cruzar','Fijar'];openModal('Reparar la red',`<p>Jonás te enseñó el orden: <strong>primero tensar la fibra, después cruzarla y finalmente fijar el nudo</strong>.</p><div class="chip-row"><span class="chip">Nudo ${knotStep+1} de 3</span></div><div class="modal-actions">${['Cruzar','Fijar','Tensar'].map(k=>btn(k,'knot:'+k)).join('')}</div><p class="muted">La cuerda solo se consume cuando terminas la reparación.</p>`,'MINIJUEGO · ARTESANÍA');}
function knot(k){const order=['Tensar','Cruzar','Fijar'];if(k===order[knotStep]){knotStep++;if(knotStep===3){spend('cuerda');gain('red');setFlag('netDone');remember('Reparé la red de Jonás con paciencia. El pescador me invitó a volver al lago.');render();simple('La red está reparada','«Buen trabajo», dice Jonás. «Hay días en que una cuerda vale más que una gran promesa». Tu ayuda ha quedado registrada.',[['Ir a pescar','go:shore'],['Continuar','modalClose']],'MISIÓN COMPLETADA');}else repairPuzzle();}else{knotStep=0;toast('El nudo se soltó. Inténtalo otra vez.');repairPuzzle();}}
function talkMara(){dialog('Mara','mara','Comerciante de la aldea','«Queda una cuerda buena, pero debo pagar al tejedor. Si le llevas la red reparada a Jonás, podrá salir a pescar y quizá nos ayude a todos».',[['Comprar cuerda (1 moneda)','buyCord'],['Preguntar por el camino de los olivos','maraTrail'],['Despedirse','modalClose']]);}
function maraTrail(){simple('El camino del norte','Mara señala los olivos: «Por allí suelen pasar viajeros, aunque algunos regresan agotados. Si vas, lleva agua».', [['Caminar hacia los olivos','go:olive'],['Volver al mercado','modalClose']]);}
function buyCord(){if(flag('cordBought'))return simple('Ya compraste cuerda','La cuerda está guardada en tu bolsa.');if(!has('moneda'))return simple('Sin monedas suficientes','No dispones de una moneda para pagar al tejedor. Puedes volver a tu casa y buscar en la bolsa de viaje.');spend('moneda');gain('cuerda');setFlag('cordBought');remember('Compré cuerda de cáñamo en el mercado.');render();simple('Cuerda adquirida','El comerciante te entrega fibras resistentes y señala cómo anudarlas.',[['Llevarla a Jonás','go:dock'],['Seguir explorando','modalClose']]);}
function talkIrit(){if(flag('iritDone'))return dialog('Irit','irit','Curandera','«Has vuelto, Natán. Hoy aprendiste a mirar antes de tomar. Si vuelves a salir, no olvides llevar agua».',[['Despedirse','modalClose']]);if(!flag('iritTalk')){setFlag('iritTalk');remember('Irit necesita dos pequeñas porciones de una planta de flores violetas y hojas finas.');}dialog('Irit','irit','Curandera de la aldea',has('plantas',2)?'«¡Las has encontrado! Son justo las plantas que buscaba para preparar mi mezcla. Gracias por no recoger las otras».':'«Necesito dos porciones de la planta de flores violetas y hojas estrechas que crece más allá del muro. No recojas las bayas rojas: no las he pedido».',has('plantas',2)?[['Entregar las plantas','giveHerbs'],['Guardar para después','modalClose']]:[['Salir al campo','go:herbs'],['Preguntar por la vida de Jesús','iritFaith'],['Volver luego','modalClose']]);}
function iritFaith(){dialog('Irit','irit','Curandera de la aldea','«He visto a algunos de sus seguidores ayudar a familias que no tenían nada. No sé si entiendo todo lo que dice el Maestro; sí entiendo lo que significa acompañar a quien sufre».',[['Recoger plantas','go:herbs'],['Despedirse','modalClose']]);}
function herbPuzzle(){openModal('Identificar las plantas',`<p>Busca <strong>flores violetas y hojas finas</strong>. Es una pista ficticia para esta misión, no una guía para usar plantas medicinales reales.</p><div class="grid-tiles"><button class="choice-item" data-run="herb:wrong"><img src="${asset('item_flower')}" alt="Flores blancas"><span>Flores blancas grandes</span></button><button class="choice-item" data-run="herb:correct"><img src="${asset('item_herb')}" alt="Flores violetas"><span>Flores violetas, hojas finas</span></button><button class="choice-item" data-run="herb:wrong"><img src="${asset('item_olives')}" alt="Bayas oscuras"><span>Bayas y hojas gruesas</span></button><button class="choice-item" data-run="herb:wrong"><img src="${asset('item_snare')}" alt="Vegetación seca"><span>Hierba seca, sin flores</span></button></div><p class="muted">Porciones recogidas: ${Math.min(state.inv.plantas||0,2)} / 2</p>`,'MINIJUEGO · OBSERVACIÓN');}
function herbsCorrect(){if(has('plantas',2))return simple('Cesta llena','Ya tienes las dos porciones solicitadas.',[['Volver con Irit','go:irit']]);gain('plantas');render();if(has('plantas',2))simple('Ya tienes suficiente','Has recogido dos porciones. Irit te espera en el patio.',[['Entregar a Irit','go:irit'],['Cerrar','modalClose']]);else{toast('Una planta correcta. Falta otra.');herbPuzzle();}}
function giveHerbs(){if(flag('iritDone'))return simple('Trabajo terminado','Irit ya recibió tus plantas.');if(!has('plantas',2))return simple('Faltan plantas','Necesitas dos porciones de la planta descrita por Irit.');spend('plantas',2);setFlag('iritDone');gain('agua');remember('Entregué plantas a Irit y recibí agua para el camino.');render();simple('El favor de Irit','Irit agradece tu cuidado y te da un cántaro de agua. «Llévalo. Quizá alguien lo necesite más que tú».',[['Continuar','modalClose']],'MISIÓN COMPLETADA');}
function track(){if(flag('trackSolved'))return simple('Ya conoces el rastro','Una liebre pequeña cruzó este sendero. Más arriba hay voces que vienen del camino.');openModal('Leer las huellas',`<p>Unas marcas pequeñas van entre los matorrales. No tienen forma de pezuña y aparecen muy próximas entre sí. ¿Qué animal pasó por aquí?</p><div class="grid-tiles"><button class="choice-item" data-run="track:wrong"><img src="${asset('item_goat')}" alt="Cabra"><span>Cabra de montaña</span></button><button class="choice-item" data-run="track:correct"><img src="${asset('item_hare')}" alt="Liebre"><span>Liebre</span></button></div>`,'MINIJUEGO · RASTREO');}
function trackResult(correct){if(!correct)return simple('Observa otra vez','Esas huellas no tienen dos pezuñas separadas. Mira la longitud y la dirección de los saltos.',[['Revisar las huellas','track'],['Cerrar','modalClose']]);setFlag('trackSolved');remember('Identifiqué el rastro de una liebre entre los olivos.');render();simple('Una liebre entre los olivos','La encuentras escondida bajo la sombra. Puedes dejarla seguir su camino o llevarte alimento. La decisión no cambia una barra de bondad; afectará tus recursos.',[['Dejarla marchar','hareSpare'],['Cazar para conseguir alimento','hareCatch']],'ELECCIÓN DE NATURALEZA');}
function hareChoice(catchIt){if(!flag('hareDecided')){setFlag('hareDecided');state.choices.hare=catchIt?'cazar':'dejar';if(catchIt)gain('carne');remember(catchIt?'Cacé una liebre para conseguir alimento.':'Dejé marchar a la liebre que encontré en los olivos.');}render();simple('El sendero continúa',catchIt?'Decides llevarte alimento. Un ruido cercano te recuerda que este lugar no está deshabitado.':'La liebre desaparece entre las raíces. Entonces escuchas una voz apagada, más allá de las rocas.',[['Seguir hacia la voz','go:injured'],['Regresar','modalClose']]);}
function wounded(){if(flag('woundedChoice'))return simple('Una decisión tomada',state.choices.wounded==='water'?'El hombre bebió de tu agua y espera poder volver a levantarse.':state.choices.wounded==='food'?'El hombre aceptó tu alimento. Prometió recordar el gesto.':state.choices.wounded==='people'?'Algunos vecinos han salido a buscar al viajero tras tu aviso.':'Decidiste continuar sin detenerte. La imagen del viajero te acompaña.',[['Continuar','modalClose']]);let choices=[];if(has('agua'))choices.push(['Compartir tu agua','wounded:water']);if(has('pez')||has('carne')||has('pan'))choices.push(['Compartir alimento','wounded:food']);choices.push(['Volver al pueblo para pedir ayuda','wounded:people'],['Seguir sin intervenir','wounded:leave']);simple('El viajero exhausto','El hombre te mira sin exigir nada. ¿Qué harás?',choices,'DECISIÓN · MISERICORDIA');}
function woundedResult(choice){if(flag('woundedChoice'))return wounded();setFlag('woundedChoice');state.choices.wounded=choice;const msgs={water:'Compartiste agua y permaneciste junto al viajero hasta que pudo respirar con calma.',food:'Compartiste alimento y le señalaste el camino de la aldea.',people:'Regresaste a la aldea para pedir ayuda. No pudiste quedarte, pero otros fueron a buscarlo.',leave:'Continuaste tu camino. La decisión te inquieta más de lo que esperabas.'};if(choice==='water')spend('agua');if(choice==='food'){if(has('pez'))spend('pez');else if(has('carne'))spend('carne');else spend('pan');}remember(msgs[choice]);render();simple('El camino sigue',msgs[choice],[['Regresar a los olivos','go:olive'],['Cerrar','modalClose']]);}
function talkSimeon(){if(!flag('simeonTalk')){setFlag('simeonTalk');remember('Siméon conocía a mi maestro y guarda una nota cifrada.');}dialog('Siméon','simeon','Viejo escriba',flag('simeonPuzzle')?'«Ya tienes el fragmento. Quien escondió ese mensaje sabía que podía perderse entre las piedras».':'«Tu maestro vino aquí buscando noticias sobre una familia. Dejó tres símbolos en una tablilla. El orden está escondido en estas palabras: primero el olivo marca la sombra; luego el agua borra los pasos; por último la piedra conserva el nombre».',[['Examinar la tablilla','scriptPuzzle'],['Preguntar por Jesús','simeonFaith'],['Salir','modalClose']]);}
function simeonFaith(){dialog('Siméon','simeon','Viejo escriba','«He copiado leyes durante toda mi vida, pero hay enseñanzas que no caben en un pergamino. Las recordamos mejor cuando alguien las pone en práctica».',[['Volver a la tablilla','scriptPuzzle'],['Cerrar','modalClose']]);}
function scriptPuzzle(){if(flag('simeonPuzzle'))return simple('Nota reconstruida','La tablilla señala un manantial al pie de las antiguas piedras, junto a un olivo. Puedes ir a buscarlo.',[['Visitar el manantial','go:spring'],['Cerrar','modalClose']]);openModal('Los tres símbolos',`<p>Ordena las señales de la tablilla. <strong>Primero</strong> el árbol marca la sombra; <strong>después</strong> el agua borra los pasos; <strong>al final</strong> la piedra conserva el nombre.</p><div class="chip-row"><span class="chip">${scriptStep} de 3 símbolos ordenados</span></div><div class="modal-actions">${['Piedra','Olivo','Agua'].map(k=>btn(k,'script:'+k)).join('')}</div>`,'ENIGMA · MANUSCRITO');}
function scriptChoose(k){let order=['Olivo','Agua','Piedra'];if(k===order[scriptStep]){scriptStep++;if(scriptStep===3){setFlag('simeonPuzzle');gain('nota');remember('Descifré la nota de Siméon: una pista conduce al antiguo manantial.');render();simple('Un mapa incompleto','Las marcas ordenadas revelan un camino entre olivos hacia el manantial. En el reverso alguien dibujó una piedra con musgo.',[['Ir al manantial','go:spring'],['Cerrar','modalClose']],'PISTA DESCUBIERTA');}else scriptPuzzle();}else{scriptStep=0;toast('El orden no encaja. Relee la descripción.');scriptPuzzle();}}
function springPuzzle(){if(flag('springSolved'))return simple('La piedra desplazada','El mensaje ya está en tu bolsa. Puedes volver a leerlo en el inventario.',[['Explorar las ruinas','go:ruins'],['Cerrar','modalClose']]);if(!flag('simeonPuzzle'))return simple('Todavía no conoces la pista','Revisa primero los papeles de Siméon.');simple('Las marcas del canal','El canal principal desaparece junto a una piedra cubierta de musgo. Otras piedras presentan surcos secos. ¿Dónde buscarías un mensaje oculto?', [['Bajo la piedra con musgo','spring:correct'],['En el surco seco que termina al sol','spring:wrong'],['En el borde más alto del arco','spring:wrong']],'ENIGMA · MANANTIAL');}
function springResult(correct){if(!correct)return simple('Una piedra cualquiera','Solo encuentras polvo. La nota hablaba de un lugar por donde pasaba el agua; busca señales de humedad.',[['Volver a investigar','springPuzzle']]);setFlag('springSolved');gain('mensaje');remember('Encontré un mensaje de mi maestro: intentaba proteger a personas que viajaban sin recursos.');render();simple('El mensaje del maestro','Detrás de la piedra encuentras un pequeño pergamino: «Si no regreso, busca a las personas que dejé atrás. Lo que importa no es el escondite, sino lo que hagamos por ellas». Son palabras de un personaje ficticio, no un texto bíblico.',[['Explorar las ruinas','go:ruins'],['Regresar al pueblo','go:village']],'MISIÓN COMPLETADA');}
function reflect(){if(state.completed)return recap();let n='Las palabras del Maestro todavía resuenan en el aire. Natán no está entre los Doce. Es un seguidor más, uno de tantos que deberán decidir cómo vivir lo que han escuchado.';simple('Lo que queda al escuchar',n,[['Quiero aprender a vivirlo','end:practice'],['Necesito tiempo para comprender','end:ponder'],['Guardar silencio y recordar','end:silence']],'EL ENCUENTRO');}
function complete(choice){state.completed=true;state.choices.reflection=choice;remember('Escuché desde la multitud la enseñanza de Jesús sobre la misericordia, la paz y el sufrimiento (Mateo 5,1–12).');saveData();render();recap();}
function recap(){let detail=state.choices.wounded==='water'||state.choices.wounded==='food'?'Recuerdas el agua y el alimento que compartiste con un desconocido.':state.choices.wounded==='people'?'Recuerdas haber buscado ayuda para el viajero exhausto.':state.choices.wounded==='leave'?'Recuerdas al hombre que quedó junto al camino. La decisión sigue abierta en tu interior.':'Todavía hay personas en los caminos que no has conocido.';let r=state.choices.reflection==='practice'?'Decides que escuchar será el principio, no el final.':state.choices.reflection==='ponder'?'No tienes todas las respuestas; aun así, deseas seguir buscando.':'Guardas silencio. A veces el recuerdo prepara una decisión futura.';openModal('Fin del capítulo I',`<img class="world-map" src="${asset('jesus')}" alt="Una multitud escucha a Jesús sobre la colina"><p class="lead">${esc(r)}</p><p>${esc(detail)}</p><div class="reflection"><div class="quote-ref">MATEO 5,1–12</div><p>Las bienaventuranzas inspiran esta escena. La historia de Natán y sus conversaciones son ficción ambientada en el mundo de los Evangelios.</p></div><div class="chip-row"><span class="chip">${state.visited.length} lugares visitados</span><span class="chip">${state.logs.length} recuerdos</span><span class="chip">${progress()} misiones esenciales</span></div><div class="modal-actions">${btn('Seguir explorando Galilea','go:village')}${btn('Leer mi diario completo','journal')}${btn('Ver la siguiente etapa del viaje','nextChapter')}</div>`,'LOS QUE ESCUCHAN · EPÍLOGO');}
function nextChapter(){simple('Próximo episodio · El camino a Magdala','La historia continuará por los caminos de Galilea. La futura versión añadirá nuevos personajes, enigmas, decisiones y un vínculo más profundo con los discípulos de Jesús. Este capítulo ya tiene un desenlace completo.',[['Seguir explorando','go:village']],'AVANCE NARRATIVO');}
function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SENDAS_partida_capitulo1.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Partida exportada.');}
function importSave(){openModal('Importar partida',`<p>Selecciona un archivo JSON creado con SENDAS ilustrada 1.0. Esto sustituirá tu progreso actual.</p><input id="import-file" type="file" accept=".json,application/json" style="width:100%;padding:15px;background:#273b30;border-radius:10px;color:#eee"><div class="modal-actions">${btn('Cancelar','modalClose')}</div>`,'GUARDADO');}
function handleImport(file){const r=new FileReader();r.onload=()=>{try{let obj=JSON.parse(r.result);if(!obj||obj.version!==1||!SCENES[obj.scene]||!obj.inv||!obj.flags||!Array.isArray(obj.logs)||!Array.isArray(obj.visited))throw Error('Formato incorrecto');state=obj;saveData();closeModal();render();toast('Partida importada.');}catch(e){toast('No se pudo importar este archivo.');}};r.readAsText(file);}
function run(action){if(!action)return;
 if(action.indexOf('go:')===0)return go(action.slice(3));
 if(action==='modalClose')return closeModal();
 if(action.indexOf('history:')===0)return showHistory(action.slice(8));
 if(action.indexOf('field:')===0)return fieldObserve(action.slice(6));
 if(action.indexOf('knot:')===0)return knot(action.slice(5));
 if(action.indexOf('script:')===0)return scriptChoose(action.slice(7));
 if(action.indexOf('spring:')===0)return springResult(action.slice(7)==='correct');
 if(action.indexOf('track:')===0)return trackResult(action.slice(6)==='correct');
 if(action.indexOf('herb:')===0){if(action.slice(5)==='correct')return herbsCorrect();toast('Esta planta no coincide con la descripción de Irit.');return herbPuzzle();}
 if(action.indexOf('wounded:')===0)return woundedResult(action.slice(8));
 if(action.indexOf('end:')===0)return complete(action.slice(4));
 switch(action){
 case'history':return openHistory();case'journal':return openJournal();case'inventory':return openInventory();case'objectives':return openObjectives();case'map':return openMap();case'help':return help();case'settings':return settings();
 case'introLetter':return introLetter();case'keepLetter':remember('Leí una nota sobre el significado de seguir las enseñanzas del Maestro.');closeModal();toast('Recuerdo añadido al diario.');return;
 case'talkJonas':return talkJonas();case'jonasFaith':return jonasFaith();case'inspectNet':return inspectNet();case'talkMara':return talkMara();case'maraTrail':return maraTrail();case'buyCord':return buyCord();case'talkIrit':return talkIrit();case'iritFaith':return iritFaith();case'herbPuzzle':return herbPuzzle();case'giveHerbs':return giveHerbs();
 case'lookLake':return simple('Un lago y muchas historias','A orillas del mar de Galilea, Natán recuerda las conversaciones de los pescadores. El lago conecta aldeas y familias, pero también separa vidas.');
 case'lookHerbs':return simple('Mirar con cuidado','Las plantas crecen entre piedras sin que nadie las haya sembrado. Natán observa su forma y su lugar antes de tocar las hojas.');
 case'fish':return fish();case'fishStop':return stopFish();case'track':return track();case'hareSpare':return hareChoice(false);case'hareCatch':return hareChoice(true);case'wounded':return wounded();case'talkSimeon':return talkSimeon();case'simeonFaith':return simeonFaith();case'scriptPuzzle':return scriptPuzzle();case'springPuzzle':return springPuzzle();case'lookRuins':setFlag('ruinsSeen');remember('Anoté fragmentos de cerámica y piedras antiguas junto al manantial ficticio.');render();return simple('Piedras y cerámica','Observas fragmentos de una vasija y las huellas de un antiguo muro. No puedes saber todavía para qué se utilizó este lugar.');
 case'lookHill':return simple('El lago al atardecer','La luz sobre el lago hace difícil distinguir las orillas. Natán recuerda que no siempre necesita comprender todo el camino para dar un primer paso.');case'reflect':return reflect();case'nextChapter':return nextChapter();
 case'fontBigger':state.fontScale=Math.min(1.35,(state.fontScale||1)+.1);saveData();render();return settings();case'fontSmaller':state.fontScale=Math.max(.9,(state.fontScale||1)-.1);saveData();render();return settings();case'export':return exportSave();case'import':return importSave();case'titleScreen':closeModal();return showStart();case'resetConfirm':return simple('¿Empezar de nuevo?','Se borrará la partida actual de este navegador. Puedes exportarla antes desde Opciones.',[['Sí, empezar de nuevo','newGame'],['Cancelar','settings']],'CONFIRMAR');case'newGame':closeModal();return startNew();
 default:return toast('Esta acción todavía no está disponible.');
 }
}
function fish(){if(!flag('jonasTalk'))return simple('Aprender a pescar','Antes de intentarlo, habla con Jonás en el muelle para conocer su trabajo.',[['Visitar a Jonás','go:dock']]);openModal('Pescar en el lago',`<p>Observa el movimiento del indicador. Cuando esté dentro de la <strong>zona verde</strong>, recoge la cuerda. Puedes intentarlo tantas veces como necesites.</p><div class="meter"><div class="meter-target"></div><div class="meter-pointer" id="fish-pointer"></div></div><div class="modal-actions">${btn('¡Recoger ahora!','fishStop','primary-btn')}${btn('Dejar la pesca','modalClose')}</div><p class="muted">Las capturas se guardarán en tu bolsa y podrás compartirlas durante el viaje.</p>`,'MINIJUEGO · PESCA');let begin=performance.now();function animate(t){let u=(t-begin)/1400;fishPos=50+48*Math.sin(u*Math.PI*2);let node=$('fish-pointer');if(!node||$('modal-root').hidden)return;node.style.left=fishPos.toFixed(1)+'%';fishFrame=requestAnimationFrame(animate);}fishFrame=requestAnimationFrame(animate);}
function stopFish(){cancelAnimationFrame(fishFrame);fishFrame=0;let success=fishPos>=28&&fishPos<=72;if(success){gain('pez');remember('Pesqué un pez en el lago y aprendí a esperar el momento adecuado.');render();simple('¡Una buena captura!','Un pez brillante queda entre tus manos. Puedes guardarlo o compartirlo con alguien que lo necesite.',[['Intentar otra vez','fish'],['Volver al muelle','go:dock'],['Cerrar','modalClose']],'PESCA COMPLETADA');}else simple('El pez escapó','La cuerda se tensó demasiado pronto o demasiado tarde. El agua vuelve a quedar tranquila.',[['Probar otra vez','fish'],['Salir','modalClose']],'PESCA');}
// Centralised events — works with injected HTML and the standalone offline build.
document.addEventListener('click',function(e){let t=e.target.closest('[data-run]');if(t){e.preventDefault();run(t.getAttribute('data-run'));return;}let p=e.target.closest('[data-panel]');if(p){e.preventDefault();run(p.getAttribute('data-panel'));}});
$('modal-close').addEventListener('click',closeModal);$('modal-backdrop').addEventListener('click',closeModal);$('btn-menu').addEventListener('click',settings);$('btn-help').addEventListener('click',help);$('btn-history').addEventListener('click',()=>showHistory());$('btn-actions-jump').addEventListener('click',()=>{const scroll=$('story-panel').querySelector('.story-scroll'),label=$('story-panel').querySelector('.story-label');scroll.scrollTo({top:label.offsetTop-scroll.offsetTop-8,behavior:'smooth'});});window.addEventListener('resize',positionHotspots);$('start-new').addEventListener('click',startNew);$('start-continue').addEventListener('click',startContinue);
document.addEventListener('change',e=>{if(e.target.id==='import-file'&&e.target.files&&e.target.files[0])handleImport(e.target.files[0]);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('modal-root').hidden)closeModal();if(e.target.tagName==='INPUT')return;if(e.key.toLowerCase()==='m'&&$('modal-root').hidden&&$('start-screen').hidden)openMap();if(e.key.toLowerCase()==='j'&&$('modal-root').hidden&&$('start-screen').hidden)openJournal();});
window.SENDAS_READONLY={getState:()=>JSON.parse(JSON.stringify(state)),version:'1.3.0'};
showStart();
})();
